<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Movie Collection</title>
<style>
:root{--bg:#10131b;--panel:#191e29;--panel2:#202735;--text:#eef2f8;--muted:#a3adbd;--accent:#f0b44c;--border:#303948;--red:#e66b6b;--green:#5dc39b}
*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,Segoe UI,Arial,sans-serif;color:var(--text)}.shell{display:flex;min-height:100vh}.sidebar{width:230px;padding:28px 18px;background:#141923;border-right:1px solid var(--border)}.brand{font-size:19px;font-weight:800;margin-bottom:35px}.brand span{color:var(--accent)}.nav{display:block;color:var(--muted);padding:12px 14px;border-radius:9px;text-decoration:none;margin:6px 0}.nav.active,.nav:hover{background:#2b303c;color:white}.nav.active{border-left:3px solid var(--accent)}.main{flex:1;padding:36px clamp(18px,4vw,52px);max-width:1400px}.top{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:28px}.eyebrow{color:var(--accent);text-transform:uppercase;letter-spacing:1.5px;font-size:11px;font-weight:700}.h1{font-size:28px;margin:7px 0}.muted{color:var(--muted)}.btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 15px;border-radius:8px;text-decoration:none;border:1px solid transparent;font-weight:650;cursor:pointer;background:var(--accent);color:#201a0e}.btn.secondary{background:var(--panel2);border-color:var(--border);color:var(--text)}.btn.danger{background:#492a31;color:#ffd4d4;border-color:#673b43}.panel{background:var(--panel);border:1px solid var(--border);border-radius:13px;padding:20px;margin-bottom:18px}.stats{display:flex;gap:14px;margin-bottom:20px}.stat{flex:1}.stat .number{font-size:26px;font-weight:800;margin-top:8px}.toolbar{display:flex;gap:10px;margin-bottom:18px}.toolbar input{flex:1}.input,select{width:100%;background:#111722;border:1px solid var(--border);border-radius:8px;padding:11px 12px;color:var(--text);outline:none}.input:focus,select:focus{border-color:var(--accent)}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:13px 12px;border-bottom:1px solid var(--border)}th{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.7px}td{font-size:14px}.actions{display:flex;gap:8px;align-items:center}.small{padding:7px 10px;font-size:12px}.badge{display:inline-block;border-radius:20px;padding:5px 9px;font-size:12px}.badge.watched{background:#1d4036;color:#9ce3c5}.badge.unwatched{background:#393449;color:#d6c7ff}.alert{padding:12px 15px;border-radius:8px;margin-bottom:16px;background:#1f4036;color:#b8f0d5;border:1px solid #2b5948}.errors{background:#4a252d;color:#ffd0d4;border-color:#713944}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field label{display:block;margin-bottom:7px;font-size:13px;color:#c9d1dd}.field.full{grid-column:1/-1}.field .help{color:var(--muted);font-size:12px;margin-top:5px}.pagination{display:flex;gap:8px;align-items:center;margin-top:16px}.footer-note{margin-top:25px;font-size:12px;color:var(--muted)}@media(max-width:760px){.sidebar{width:72px;padding:20px 8px}.brand{font-size:0;text-align:center}.brand span{font-size:18px}.nav{font-size:0;text-align:center;padding:12px 4px}.nav:after{content:'•';font-size:20px}.main{padding:20px 14px}.top{align-items:flex-start;flex-direction:column}.stats{flex-direction:column}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}}
</style></head><body><div class="shell"><aside class="sidebar"><div class="brand">MOVIE <span>COLLECTION</span></div><a class="nav active" href="{{ route('movies.index') }}">Movies</a><a class="nav" href="{{ route('movies.create') }}">Add Movie</a></aside><main class="main">@yield('content')<div class="footer-note">Movie Collection · CRUD Operations · Laravel & MySQL</div></main></div></body></html>
